@startuml

class Airline {
  + ID : string
}

class Flight {
  + ID : string
  + departure_time : datetime
  + arrival_time : datetime
}

class Airport {
  + identifier : string
}

class Pilot {
  + experience_level : int
}

enum Role {
  captain
  co-pilot
  navigator
}

class Aircraft {
  + state : string
  + position : string
}

class AircraftType {
  + name : string
}

class PilotRequirement {
  + role : Role
  + required_number : int
}

Airline "1" -- "*" Flight : operates
Airline "1" -- "*" Aircraft : owns
Flight "*" -- "1" Airport : departure_airport
Flight "*" -- "1" Airport : arrival_airport
Flight "*" -- "1" Pilot : captain
Flight "*" -- "1" Pilot : co-pilot
Flight "*" -- "1" Aircraft : uses
Aircraft "*" -- "1" AircraftType : is_of_type
AircraftType "1" -- "*" PilotRequirement : requires

@enduml

